package com.zhineng.platform.evaluation.performance.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.zhineng.platform.common.audit.OperationLogRepository;import com.zhineng.platform.common.user.service.CurrentUserService;import com.zhineng.platform.evaluation.performance.dto.PerformanceDtos;import com.zhineng.platform.evaluation.performance.excel.PerformanceExcelService;import com.zhineng.platform.evaluation.performance.repository.PerformanceRepository;import com.zhineng.platform.evaluation.performance.storage.PerformanceStorageService;
import java.io.*;import java.nio.file.*;import java.security.MessageDigest;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;
@Service @Transactional public class PerformanceService{
 private static final Set<String>TARGETS=Set.of("ORG_CODE","ORG_NAME","YEAR","PERFORMANCE_GRADE","KEY_WORK_SCORE","LEADERSHIP_RATING","REMARKS"),SCOPES=Set.of("ALL","PERFORMANCE_GRADE","KEY_WORK_SCORE","LEADERSHIP_RATING"),GRADES=Set.of("A","B","C","D","优秀","良好","合格","不合格");private static final long MAX=10L*1024*1024;
 private final PerformanceRepository repo;private final PerformanceExcelService excel;private final CurrentUserService user;private final OperationLogRepository logs;private final PerformanceStorageService storage;private final ObjectMapper json;
 public PerformanceService(PerformanceRepository r,PerformanceExcelService e,CurrentUserService u,OperationLogRepository l,PerformanceStorageService s,ObjectMapper j){repo=r;excel=e;user=u;logs=l;storage=s;json=j;}
 @Transactional(readOnly=true)public List<Map<String,Object>>mappings(){return repo.mappings();}
 public Map<String,Object>saveMapping(Long id,PerformanceDtos.MappingRequest q){String source=req(q.sourceField(),"来源字段"),target=up(q.targetField());if(!TARGETS.contains(target))bad("INVALID_TARGET","目标字段无效");long uid=user.getCurrentUser().id();long result;if(id==null)result=repo.insertMapping(source,target,Boolean.TRUE.equals(q.required()),q.sortOrder()==null?0:q.sortOrder(),uid);else{if(repo.updateMapping(id,source,target,Boolean.TRUE.equals(q.required()),q.sortOrder()==null?0:q.sortOrder(),rv(q.rowVersion()),uid)!=1)conflict("STALE_MAPPING","映射已变化");result=id;}Map<String,Object>after=repo.mapping(result);log("M2-7","FIELD_MAPPING",result,id==null?"CREATE":"UPDATE",after);return after;}
 public Map<String,Object>mappingStatus(long id,PerformanceDtos.StatusRequest q){String status=up(q.status());if(!Set.of("ACTIVE","INACTIVE").contains(status))bad("INVALID_STATUS","状态无效");if(repo.mappingStatus(id,status,rv(q.rowVersion()),user.getCurrentUser().id())!=1)conflict("STALE_MAPPING","映射已变化");return repo.mapping(id);}
 public byte[]template(){return excel.template();}
 public Map<String,Object>importFile(MultipartFile file){if(file==null||file.isEmpty())bad("EMPTY_FILE","请选择XLSX");if(file.getSize()>MAX)bad("FILE_TOO_LARGE","文件不能超过10MB");if(!"xlsx".equals(ext(file.getOriginalFilename())))bad("UNSUPPORTED_FILE","仅支持.xlsx");PerformanceExcelService.WorkbookData wb;try{wb=excel.read(file.getBytes());}catch(IOException|IllegalArgumentException e){bad("INVALID_XLSX",e.getMessage());return null;}Map<String,String>map=new HashMap<>();for(Map<String,Object>m:repo.mappings())if("ACTIVE".equals(m.get("status")))map.put(m.get("source_field").toString(),m.get("target_field").toString());if(!map.containsValue("ORG_CODE")||!map.containsValue("YEAR")||!map.containsValue("PERFORMANCE_GRADE"))bad("REQUIRED_MAPPING_MISSING","必须映射机构编码、年度和绩效等次");long uid=user.getCurrentUser().id(),batch=repo.insertBatch("ORG-"+Instant.now().toEpochMilli(),safe(file.getOriginalFilename()),file.getSize(),uid);int ok=0,fail=0,warnings=0;for(var row:wb.rows()){Map<String,String>v=new HashMap<>();for(var e:row.values().entrySet())if(map.containsKey(e.getKey()))v.put(map.get(e.getKey()),e.getValue());String raw=toJson(row.values()),code=v.get("ORG_CODE");try{Map<String,Object>org=repo.orgByCode(req(code,"机构编码"));if(org==null)throw new IllegalArgumentException("机构编码不存在");if(!"ACTIVE".equals(org.get("status")))throw new IllegalArgumentException("机构已停用");int year=Integer.parseInt(req(v.get("YEAR"),"年度"));if(year<1900||year>2999)throw new IllegalArgumentException("年度无效");String grade=req(v.get("PERFORMANCE_GRADE"),"绩效等次");if(!GRADES.contains(grade.toUpperCase(Locale.ROOT))&&!GRADES.contains(grade))throw new IllegalArgumentException("绩效等次无效");Double score=number(v.get("KEY_WORK_SCORE"));String warning=null,sourceName=trim(v.get("ORG_NAME"));if(sourceName!=null&&!sourceName.equals(org.get("unit_name"))){warning="机构名称与编码不一致，以编码为准";warnings++;}repo.insertRaw(batch,row.rowNumber(),num(org.get("id")),code,sourceName,year,grade,score,trim(v.get("LEADERSHIP_RATING")),trim(v.get("REMARKS")),raw,warning);ok++;}catch(Exception e){repo.insertError(batch,row.rowNumber(),code,raw,e.getMessage());fail++;}}repo.finishBatch(batch,wb.rows().size(),ok,fail,warnings);Map<String,Object>result=batch(batch);log("M2-7","PERFORMANCE_IMPORT",batch,"IMPORT",result);return result;}
 @Transactional(readOnly=true)public List<Map<String,Object>>batches(){return repo.batches();}
 @Transactional(readOnly=true)public Map<String,Object>batch(long id){Map<String,Object>b=repo.batch(id);if(b==null)nf("BATCH_NOT_FOUND","批次不存在");b.put("records",repo.batchRecords(id));b.put("errors",repo.errors(id));return b;}
 @Transactional(readOnly=true)public List<Map<String,Object>>records(Integer year){return repo.effective(year);}
 @Transactional(readOnly=true)public List<Map<String,Object>>corrections(){return repo.corrections();}
 @Transactional(readOnly=true)public Map<String,Object>correction(long id){Map<String,Object>c=repo.correction(id);if(c==null)nf("CORRECTION_NOT_FOUND","修正不存在");c.put("history",repo.history(id));c.put("materials",repo.materials(id));return c;}
 public Map<String,Object>saveCorrection(Long id,PerformanceDtos.CorrectionRequest q){Map<String,Object>raw=repo.raw(q.rawRecordId());if(raw==null)nf("RAW_NOT_FOUND","原始绩效记录不存在");String scope=up(q.correctionScope());if(!SCOPES.contains(scope))bad("INVALID_SCOPE","修正范围无效");validGrade(q.correctedGrade());validScore(q.correctedKeyWorkScore());String reason=req(q.correctionReason(),"修正原因");long uid=user.getCurrentUser().id(),cid;if(id==null){cid=repo.insertCorrection(q.rawRecordId(),scope,toJson(Map.of("performanceGrade",raw.get("performance_grade"),"keyWorkScore",raw.get("key_work_score")==null?"":raw.get("key_work_score"),"leadershipRating",raw.get("leadership_rating")==null?"":raw.get("leadership_rating"))),trim(q.correctedGrade()),q.correctedKeyWorkScore(),trim(q.correctedLeadershipRating()),reason,uid);repo.history(cid,null,"DRAFT","创建修正",uid);}else{if(repo.updateCorrection(id,scope,trim(q.correctedGrade()),q.correctedKeyWorkScore(),trim(q.correctedLeadershipRating()),reason,rv(q.rowVersion()),uid)!=1)conflict("CORRECTION_READ_ONLY","修正不可编辑或版本冲突");cid=id;}Map<String,Object>after=correction(cid);log("M2-8","PERFORMANCE_CORRECTION",cid,id==null?"CREATE":"UPDATE",after);return after;}
 public Map<String,Object>submit(long id,PerformanceDtos.ReviewRequest q){Map<String,Object>b=correction(id);if(!Set.of("DRAFT","REJECTED").contains(b.get("status")))conflict("CORRECTION_NOT_EDITABLE","仅草稿或驳回修正可提交");if(repo.correctionStatus(id,b.get("status").toString(),"SUBMITTED",trim(q.opinion()),rv(q.rowVersion()),user.getCurrentUser().id())!=1)conflict("STALE_CORRECTION","修正已变化");return correction(id);}
 public Map<String,Object>review(long id,PerformanceDtos.ReviewRequest q){Map<String,Object>b=correction(id);if(!"SUBMITTED".equals(b.get("status")))conflict("NOT_SUBMITTED","仅已提交修正可复核");String action=up(q.action());String to="CONFIRM".equals(action)?"CONFIRMED":"REJECT".equals(action)?"REJECTED":null;if(to==null)bad("INVALID_ACTION","复核结果无效");String opinion=req(q.opinion(),"复核意见");if(repo.correctionStatus(id,"SUBMITTED",to,opinion,rv(q.rowVersion()),user.getCurrentUser().id())!=1)conflict("STALE_CORRECTION","修正已变化");Map<String,Object>a=correction(id);log("M2-8","PERFORMANCE_CORRECTION",id,action,a);return a;}
 public Map<String,Object>upload(long id,String remarks,MultipartFile file){Map<String,Object>c=correction(id);if(!Set.of("DRAFT","REJECTED").contains(c.get("status")))conflict("CORRECTION_READ_ONLY","提交后不能上传材料");if(file==null||file.isEmpty()||file.getSize()>MAX)bad("INVALID_FILE","材料为空或超过10MB");String extension=ext(file.getOriginalFilename());PerformanceStorageService.Stored stored=null;try{stored=storage.store(file.getInputStream(),extension);long aid=repo.insertAttachment(id,safe(file.getOriginalFilename()),stored.storedName(),stored.relativePath(),file.getContentType(),extension,file.getSize(),sha(storage.resolve(stored.relativePath())),trim(remarks),user.getCurrentUser().id());return repo.attachment(aid);}catch(Exception e){if(stored!=null)storage.deleteQuietly(stored.relativePath());bad("UPLOAD_FAILED","上传失败："+e.getMessage());return null;}}
 @Transactional(readOnly=true)public Download download(long id)throws IOException{Map<String,Object>a=repo.attachment(id);if(a==null)nf("ATTACHMENT_NOT_FOUND","材料不存在");Path p=storage.read(a.get("storage_path").toString());return new Download(p,a.get("original_name").toString(),a.get("content_type")==null?"application/octet-stream":a.get("content_type").toString());}
 private Double number(String v){if(trim(v)==null)return null;try{double d=Double.parseDouble(v);if(d<0||d>100)throw new Exception();return d;}catch(Exception e){throw new IllegalArgumentException("重点工作得分必须为0～100");}}
 private void validScore(Double v){if(v!=null&&(v<0||v>100))bad("INVALID_SCORE","修正得分必须为0～100");}
 private void validGrade(String v){if(trim(v)!=null&&!GRADES.contains(v.toUpperCase(Locale.ROOT))&&!GRADES.contains(v))bad("INVALID_GRADE","修正等次无效");}
 private String sha(Path p)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}
 private String toJson(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}
 private String ext(String n){if(n==null||!n.contains("."))return "";return n.substring(n.lastIndexOf('.')+1).toLowerCase(Locale.ROOT);}private String safe(String n){return n==null?"file":Path.of(n).getFileName().toString().replaceAll("[\\r\\n]","_");}
 private String req(Object v,String l){String s=trim(v);if(s==null)throw new IllegalArgumentException(l+"不能为空");return s;}private String trim(Object v){if(v==null)return null;String s=v.toString().trim();return s.isEmpty()?null:s;}private String up(String v){return v==null?null:v.trim().toUpperCase(Locale.ROOT);}private int rv(Integer v){if(v==null)bad("ROW_VERSION_REQUIRED","缺少版本号");return v;}private long num(Object v){return((Number)v).longValue();}
 private void log(String m,String t,long id,String a,Object after){logs.success(m,t,id,a,user.getCurrentUser().id(),"LOCAL","/api/org-performance",null,toJson(after));}
 private void bad(String c,String m){throw new PerformanceException(HttpStatus.BAD_REQUEST,c,m);}private void conflict(String c,String m){throw new PerformanceException(HttpStatus.CONFLICT,c,m);}private void nf(String c,String m){throw new PerformanceException(HttpStatus.NOT_FOUND,c,m);}
 public record Download(Path path,String name,String type){}
}
